10	// "Sync now": a handful of MCP reads and one database call, so it runs inline.
11	export async function POST(_request: Request, { params }: { params: Promise<{ id: string }> }) {
12	  let context: Awaited<ReturnType<typeof requireWorkspace>>;
13	  try { context = await requireWorkspace(); } catch { return NextResponse.json({ error: "Unauthorized" }, { status: 401 }); }
14	  if (!scalableConfigured()) return NextResponse.json({ error: "Scalable is not configured" }, { status: 503 });
15	  const id = z.string().uuid().safeParse((await params).id);
16	  if (!id.success) return NextResponse.json({ error: "Not found" }, { status: 404 });
17	  const connection = await context.supabase.from("scalable_connections").select("status, last_synced_at").eq("id", id.data).eq("workspace_id", context.workspace.id).maybeSingle();
18	  if (connection.error || !connection.data) return NextResponse.json({ error: "Not found" }, { status: 404 });
19	  if (connection.data.status !== "active") return NextResponse.json({ error: "Connect Scalable again before syncing" }, { status: 409 });
20	  if (connection.data.last_synced_at && Date.now() - Date.parse(connection.data.last_synced_at) < 30_000)
21	    return NextResponse.json({ error: "Synced moments ago. Try again in a minute." }, { status: 429 });
22	  try {
23	    const { changed } = await syncScalable(id.data, context.workspace.id);
24	    return NextResponse.json({ status: "synced", changed });
25	  } catch (error) {
26	    if (error instanceof ScalableError && error.expired) return NextResponse.json({ error: error.message }, { status: 409 });
27	    return NextResponse.json({ error: "The Scalable sync failed. Try again." }, { status: 502 });
28	  }
29	}
