10	type BankImport = { importId: string; rowCount: number; uid: string; lastBookedOn: string };
11	
12	// One sync = one ordinary import per bank account, run through the existing import workflow
13	// so dedupe (bank id as external_id), review, undo and source history are unchanged.
14	export async function syncBankConnection(connectionId: string, workspaceId: string, psu?: PsuContext) {
15	  "use workflow";
16	  const { imports, error } = await stageBankImports(connectionId, workspaceId, psu);
17	  for (const item of imports) {
18	    // importFile runs flattened into this run, so a throw from its optional tail (first review,
19	    // agent team) would end the sync here. The import's stored status is the truth; finishBankSync reads it.
20	    try { await importFile(item.importId, workspaceId, item.rowCount, 1); } catch {}
21	  }
22	  await finishBankSync(connectionId, workspaceId, imports, error);
23	}
