1	// A sync runs from sync_started_at until finishBankSync stamps last_synced_at. One that never
2	// finished (a crashed run) stops counting as running after 15 minutes so it can be retried.
3	export const SYNC_STALE_MS = 15 * 60_000;
4	
5	export function syncRunning(connection: { sync_started_at: string | null; last_synced_at: string | null }, now = Date.now()) {
6	  if (!connection.sync_started_at) return false;
7	  const started = Date.parse(connection.sync_started_at);
8	  return now - started < SYNC_STALE_MS && (!connection.last_synced_at || Date.parse(connection.last_synced_at) < started);
9	}
