57	export type WealthValue = { id: string; name: string; amount_minor: string; currency_code: string; as_of: string; linked_account_id: string | null };
58	/** A valuation counts in current net worth only when dated today, except money lent to or owed to a person:
59	 * that is a fixed amount, not a market value, so it stays current from the day it changed hands until repaid. */
60	export const currentOn = (row: Pick<WealthValue, "name" | "as_of">, today: string) => row.as_of === today || (row.as_of < today && parseIouName(row.name) !== null);
61	export function wealthEvidence(rows: WealthValue[], today: string, basis: "current" | "observed" = "current") {
62	  dateValue(today);
63	  const included: { id: string; name: string; amountMinor: bigint; currencyCode: string; asOf: string; provenance: string }[] = [];
64	  const excludedLinked: string[] = []; const missingInputs: string[] = [];
65	  for (const row of rows) {
66	    if (row.linked_account_id) { excludedLinked.push(row.id); continue; }
67	    dateValue(row.as_of);
68	    if (row.as_of > today || (basis === "current" && !currentOn(row, today))) { missingInputs.push(`valuation:${row.id}:${row.as_of > today ? "future" : "historical"}`); continue; }
69	    if (typeof row.amount_minor !== "string" || !/^-?\d+$/.test(row.amount_minor)) throw new Error("Invalid wealth money");
70	    minorDigits(row.currency_code);
71	    included.push({ id: row.id, name: row.name, amountMinor: BigInt(row.amount_minor), currencyCode: row.currency_code, asOf: row.as_of, provenance: "manual valuation" });
72	  }
73	  return { included, excludedLinked, missingInputs, valuationBasis: basis,
74	    sourceCoverage: buildSourceCoverage({ from: today, to: today, recordBasis: "manual_wealth" }, []),
75	    manualRecords: { accepted: rows.length, included: included.length, excludedLinked: excludedLinked.length, excludedDated: rows.length - included.length - excludedLinked.length } };
76	}

