29	// Turns internal missing-input keys (e.g. "balance:<id>:missing") into short,
30	// deduplicated sentences. Unknown keys pass through unchanged.
31	export function describeMissingInputs(keys: string[], names: Map<string, string> = new Map()): string[] {
32	  const label = (ref: string) => names.get(ref) ?? (uuid.test(ref) ? "An account" : ref);
33	  const describe = (key: string): string => {
34	    const named = /^(.+) for (.+)$/.exec(key);
35	    if (named) return `${describe(named[1]).replace(/^(An account|A balance)/, named[2])}`;
36	    const [kind, ...rest] = key.split(":");
37	    if (kind === "balance" || kind === "available-balance") return !rest[1] || rest[1] === "missing" ? `${label(rest[0])} needs a current balance` : rest[1] === "stale" ? `${label(rest[0])} has an out-of-date balance` : `${label(rest[0])} balance is ${rest.slice(1).join(":")}`;
38	    if (kind === "rate") return `An account needs a ${rest.join(":").replace("->", " to ")} exchange rate`;
39	    if (kind === "currency") return `Currency ${rest[0]} is not supported`;
40	    if (kind === "fx") return rest.length > 1 && rest[0] !== "scenario" ? `${label(rest[1])} needs an exchange rate` : "An exchange rate is missing";
41	    if (kind === "valuation") return rest[1] === "future" ? "A valuation is dated in the future" : "A valuation is not from today";
42	    if (kind === "debt") return `A debt ${rest.slice(1).join(":") || "needs repayment terms"}`;
43	    if (kind === "occurrence") return `${rest[0]} on ${rest[1]}: evidence changed, review the association`;
44	    return key;
45	  };
46	  return [...new Set(keys.map(describe))];
47	}

12	export function reviewNetWorth(accountTotals: Record<string, string | null>, wealth: WealthValue[], today: string) {
13	  const dated = wealthEvidence(wealth, today);
14	  const currencies = [...new Set([...Object.keys(accountTotals), ...wealth.filter(row => !row.linked_account_id).map(row => row.currency_code)])];
15	  return Object.fromEntries(currencies.map(currency => {
16	    if (accountTotals[currency] === null || wealth.some(row => !row.linked_account_id && row.currency_code === currency && row.as_of !== today)) return [currency, null];
17	    const total = BigInt(accountTotals[currency] ?? "0") + dated.included.filter(row => row.currencyCode === currency).reduce((sum, row) => sum + row.amountMinor, 0n);
18	    return [currency, total.toString()];
19	  }));

