"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";

export async function syncIfVisible(refresh: () => void) {
  if (document.visibilityState !== "visible") return;
  const response = await fetch("/api/sync/open", { method: "POST" }).catch(() => null);
  if (response?.ok && (await response.json()).refresh) refresh();
}

/** Syncs when Moneo is opened or returned to, and updates the page once fresher numbers land. Renders nothing. */
export function SyncOnOpen() {
  const router = useRouter();
  useEffect(() => {
    const sync = () => void syncIfVisible(router.refresh);
    sync();
    document.addEventListener("visibilitychange", sync);
    return () => document.removeEventListener("visibilitychange", sync);
  }, [router]);
  return null;
}

import { afterEach, expect, it, vi } from "vitest";
import { syncIfVisible } from "./sync-on-open";

afterEach(() => vi.unstubAllGlobals());
const setup = (visibilityState: string, fetcher: () => Promise<Response>) => {
  vi.stubGlobal("document", { visibilityState });
  const fetchMock = vi.fn(fetcher);
  vi.stubGlobal("fetch", fetchMock);
  return { fetchMock, refresh: vi.fn() };
};

it("updates the page once fresher numbers landed", async () => {
  const { fetchMock, refresh } = setup("visible", async () => Response.json({ refresh: true }));
  await syncIfVisible(refresh);
  expect(fetchMock).toHaveBeenCalledWith("/api/sync/open", { method: "POST" });
  expect(refresh).toHaveBeenCalledTimes(1);
});

it("leaves the page alone when nothing ran, when offline, and when the app is in the background", async () => {
  const idle = setup("visible", async () => Response.json({ refresh: false }));
  await syncIfVisible(idle.refresh);
  expect(idle.refresh).not.toHaveBeenCalled();

  const offline = setup("visible", async () => { throw new Error("offline"); });
  await syncIfVisible(offline.refresh);
  expect(offline.refresh).not.toHaveBeenCalled();

  const hidden = setup("hidden", async () => Response.json({ refresh: true }));
  await syncIfVisible(hidden.refresh);
  expect(hidden.fetchMock).not.toHaveBeenCalled();
});

import type { SupabaseClient } from "@supabase/supabase-js";

type Connection = { status: string; last_error: string | null };

/** One short sentence for a connection that needs the owner, or null when it is fine. */
export function syncProblem(name: string, { status, last_error }: Connection) {
  if (status === "expired" || status === "error") return `${name} needs reconnecting, so its numbers may be old.`;
  return last_error ? `${name} could not sync, so its numbers may be old. Moneo tries again by itself.` : null;
}

/** What Home must say about syncing. A failed check says nothing: the numbers still show. */
export async function loadSyncProblems(db: SupabaseClient, workspaceId: string) {
  const [banks, scalable] = await Promise.all([
    db.from("bank_connections").select("aspsp_name, status, last_error").eq("workspace_id", workspaceId).neq("status", "pending"),
    db.from("scalable_connections").select("status, last_error").eq("workspace_id", workspaceId).neq("status", "pending"),
  ]);
  return [...(banks.data ?? []).map(row => syncProblem(row.aspsp_name, row)), ...(scalable.data ?? []).map(row => syncProblem("Scalable", row))]
    .filter((problem): problem is string => problem !== null);
}

