// Read-only probe. Only ever calls the tools in ALLOWED. Prints counts, dates and whether the replay matches, not holdings or amounts.
import { serviceDb } from "@/lib/bank/server";
import { withScalable } from "@/lib/scalable/server";

const ALLOWED = new Set(["list_portfolio_transactions", "get_security_chart", "get_portfolio_holdings", "get_portfolio_cash_breakdown", "get_portfolio_overview", "get_transaction_details"]);
type Row = Record<string, any>;
const tally = (rows: Row[], key: (row: Row) => string) => { const out: Record<string, number> = {}; for (const row of rows) out[key(row)] = (out[key(row)] ?? 0) + 1; return out; };
const mask = (value: unknown): unknown => {
  if (Array.isArray(value)) return value.length ? [mask(value[0]), `…${value.length}`] : [];
  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, mask(v)]));
  return value === null ? "null" : typeof value;
};
const sign = (value: unknown) => value == null ? "none" : Number(value) > 0 ? "+" : Number(value) < 0 ? "-" : "0";

async function main() {
  const db = serviceDb();
  const { data } = await db.from("scalable_connections").select("id, workspace_id").eq("status", "active").single();
  await withScalable(data!.id, data!.workspace_id, async mcp => {
    const call = (name: string, args: Record<string, unknown> = {}) => { if (!ALLOWED.has(name)) throw new Error("blocked " + name); return mcp.callTool(name, args) as Promise<Row>; };
    const all: Row[] = [], cryptoAll: Row[] = [];
    let cursor: string | undefined, cryptoCursor: string | undefined, pages = 0, total: unknown;
    do {
      const page = await call("list_portfolio_transactions", { pageSize: 100, ...(cursor ? { cursor } : {}), ...(cryptoCursor ? { cryptoCursor } : {}) });
      all.push(...(page.transactions ?? [])); cryptoAll.push(...(page.crypto?.transactions ?? []));
      cursor = page.page?.nextCursor ?? undefined; cryptoCursor = page.crypto?.page?.nextCursor ?? undefined; total = page.page?.totalCount; pages++;
    } while ((cursor || cryptoCursor) && pages < 100);
    const dates = all.map(row => row.lastEventAt).sort();
    console.log("TX", { count: all.length, total, pages, first: dates[0]?.slice(0, 10), last: dates.at(-1)?.slice(0, 10), crypto: cryptoAll.length, cryptoFirst: cryptoAll.map(row => row.lastEventAt).sort()[0]?.slice(0, 10) });
    console.log("STATUS", tally(all, row => row.status), "CANCEL", tally(all, row => String(row.isCancellation)));
    console.log("TYPES (kind|category|type|side|qtySign|amtSign)", tally(all, row => {
      const body = row.security ?? row.cash ?? row.nonTradeSecurity ?? row.eltif ?? {};
      return [row.kind, row.category, body.transactionType, body.side, sign(body.quantity), sign(body.amount)].join("|");
    }));
    console.log("CRYPTO TYPES", tally(cryptoAll, row => [row.kind, row.category, row.status, row.transactionType, row.side, sign(row.amount)].join("|")));
    const nonTrade = all.find(row => row.nonTradeSecurity); if (nonTrade) console.log("NONTRADE SHAPE", JSON.stringify(mask(nonTrade.nonTradeSecurity)));
    const cashRow = all.find(row => row.cash); if (cashRow) console.log("CASH SHAPE", JSON.stringify(mask(cashRow.cash)));

    const holdings = await call("get_portfolio_holdings");
    console.log("CRYPTO HOLDING SHAPE", JSON.stringify(mask(holdings.cryptoHoldings)));
    const held = new Map<string, number>((holdings.holdings ?? []).filter((row: Row) => row.position?.filled > 0).map((row: Row) => [row.isin, Number(row.position.filled)]));

    // Replay shares: done trades only.
    const DONE = /settled|filled|executed|completed|done/i;
    const shares = new Map<string, number>();
    for (const row of all) {
      if (row.isCancellation || !DONE.test(row.status)) continue;
      const body = row.security ?? row.nonTradeSecurity;
      if (!body?.isin || body.quantity == null) continue;
      const qty = Math.abs(Number(body.quantity)), side = String(body.side ?? body.transactionType ?? "").toLowerCase();
      shares.set(body.isin, (shares.get(body.isin) ?? 0) + (/sell/.test(side) ? -qty : qty));
    }
    const isins = new Set([...held.keys(), ...shares.keys()]);
    let match = 0; const off: string[] = [];
    for (const isin of isins) { const a = held.get(isin) ?? 0, b = shares.get(isin) ?? 0; if (Math.abs(a - b) < 1e-6) match++; else off.push(`${isin.slice(0, 2)}… heldZero=${a === 0} replayZero=${Math.abs(b) < 1e-9} ratio=${a && b ? (b / a).toFixed(4) : "-"}`); }
    console.log("SHARE REPLAY", { securities: isins.size, currentlyHeld: held.size, match, off });

    const cash = await call("get_portfolio_cash_breakdown");
    let replayCash = 0;
    for (const row of all) { if (row.isCancellation || !DONE.test(row.status)) continue; const body = row.security ?? row.cash ?? row.nonTradeSecurity ?? row.eltif; if (body?.amount != null) replayCash += Number(body.amount); }
    for (const row of cryptoAll) { if (!DONE.test(row.status)) continue; if (row.amount != null) replayCash += Number(row.amount); }
    console.log("CASH REPLAY raw sum minus balance (EUR)", (replayCash - Number(cash.cash?.cashBalance)).toFixed(2));

    for (const isin of [...isins].slice(0, 25)) {
      for (const timeframe of ["max", "one_year"]) {
        try {
          const chart = await call("get_security_chart", { isin, timeframe });
          const times = (chart.dataPoints ?? []).map((point: Row) => Date.parse(point.timestampUtc)).sort((a: number, b: number) => a - b);
          const gaps = times.slice(1).map((t: number, i: number) => (t - times[i]) / 86_400_000).sort((a: number, b: number) => a - b);
          console.log("CHART", isin.slice(0, 2) + "…", timeframe, { points: times.length, first: times.length ? new Date(times[0]).toISOString().slice(0, 10) : null, medianGapDays: gaps[gaps.length >> 1]?.toFixed(2), maxGapDays: gaps.at(-1)?.toFixed(2) });
        } catch (error) { console.log("CHART", isin.slice(0, 2) + "…", timeframe, "failed:", String(error).slice(0, 120)); }
      }
    }
  });
}
main().catch(error => { console.error(String(error)); process.exit(1); });

