148	/** Which money counts today and on past days, worked out once from the evidence. */
149	export function netWorthModel(evidence: NetWorthEvidence) {
150	  const { balances, items, events, scalable, transfers, legs, timeZone } = evidence;
151	  const today = calendarDate(balances.asOf, timeZone);
152	  const valuations = valuationHistory(events, items, timeZone);
153	  const firstReal = firstSyncedOn(valuations, scalable.knownIds);
154	  // Real reads of Scalable only: the current row isn't a read, its events are.
155	  const reads = valuations.filter(row => scalable.knownIds.has(row.item_id) && row.created_at < "9999");
156	  const coveredFrom = balances.ledger.reduce<string | null>((first, row) => row.status === "posted" && (first === null || row.posted_on < first) ? row.posted_on : first, null);
157	  const { windows, unresolved } = matchTransfers({ transfers: transfers.rows, legs, firstReal, reads, complete: transfers.complete, coveredFrom });
158	  const accounts = resolveBalances(balances.accounts, balances.snapshots, balances.ledger, balances.asOf, timeZone).filter(account => !account.archived_at);
159	  const active = items.filter(item => !item.removed_at);
160	  const kinds = new Map(items.map(item => [item.id, item.kind]));
161	  const dated = wealthEvidence(active, today);
162	  const calculated = { rows: scalable.rows, before: firstReal };
163	  /** Past days and today from the same inputs. Today's point is the headline's own, so the graph ends on the number above it. */
164	  const points = (dates: string[]): NetWorthPoint[] => netWorthSeries({ dates: dates.filter(date => date !== today), timeZone, accountIds: new Set(balances.accounts.map(account => account.id)), archivedOn: archiveDates(balances.accounts, ti
165	    snapshots: balances.snapshots, ledger: balances.ledger, valuations, calculated, transit: windows }).concat(dates.includes(today) ? [now] : []).sort((a, b) => a.date.localeCompare(b.date));
166	  // Every side of a window has landed by today, except a broker side no read has seen yet: that money is still the owner's.
167	  const now = currentNetWorth(today, accounts, dated.included.map(valuation => ({ ...valuation, debt: kinds.get(valuation.id) === "debt" })), transitOn(windows, today));
168	  // Money moved on the first real day is already in that value, so the comparison with the day before allows for it.
169	  const movedOnBoundaryMinor = transfers.rows.filter(row => row.on_date === firstReal && row.status === "SETTLED" && !row.is_cancellation).reduce((sum, row) => sum + BigInt(row.amount_minor), 0n);
170	
171	  /**
172	   * This month's change, split so spending and markets stay apart and something newly added isn't a gain.
173	   * `changeMinor` excludes what's newly added; the total still counts it. Moving your own money is neither.
174	   */
175	  const monthSplit = (currency: string, base = monthEnds(today, 1)[0]) => {
176	    const [basePoint] = points([base]);
177	    if (!basePoint?.known) return null;
178	    const totalChangeMinor = (netWorth(now).get(currency) ?? 0n) - (netWorth(basePoint).get(currency) ?? 0n);
179	    const isLoan = (name: string) => parseIouName(name) !== null;
180	    const portfolioBefore = !!firstReal && firstReal > base && calculated.rows.some(row => row.on_date === base);
181	    const newCovered = (id: string) => portfolioBefore && scalable.knownIds.has(id);
182	    // Loans move with the bank money that paid them, so they're never "new" and belong with money in and out.
183	    const named = new Map(items.map(item => [item.id, item.name]));
184	    const states = valuations.filter(row => row.currency_code === currency && !row.removed && !isLoan(String((row as { name?: string }).name ?? named.get(row.item_id) ?? "")));
185	    const valueOn = (date: string, rows: typeof valuations) => {
186	      const pick = new Map<string, typeof valuations[number]>();
187	      for (const row of rows) { if (row.as_of > date) continue; const prior = pick.get(row.item_id); if (!prior || row.as_of > prior.as_of || (row.as_of === prior.as_of && row.created_at >= prior.created_at)) pick.set(row.item_id, row); }
188	      return pick;
189	    };
190	    const allStates = valuations.filter(row => row.currency_code === currency && !isLoan(String((row as { name?: string }).name ?? named.get(row.item_id) ?? "")));
191	    const counted = (date: string) => [...valueOn(date, allStates).values()].filter(row => !row.removed && !row.linked_account_id);
192	    const investing = (date: string) => counted(date).filter(row => row.kind !== "debt").reduce((sum, row) => sum + BigInt(row.amount_minor), 0n)
193	      + (firstReal && date < firstReal ? BigInt(calculated.rows.find(row => row.on_date === date && row.currency_code === currency)?.total_minor ?? "0") : 0n);
194	    let newlyAddedMinor = 0n, newInvestingMinor = 0n;
195	    for (const row of counted(today)) {
196	      const first = states.filter(state => state.item_id === row.item_id && !state.linked_account_id).reduce<typeof states[number] | null>((earliest, state) => !earliest || state.as_of < earliest.as_of || (state.as_of === earliest.as_of && 
197	      if (!first || first.as_of <= base || newCovered(row.item_id)) continue;
198	      newlyAddedMinor += BigInt(first.amount_minor);
199	      if (row.kind !== "debt") newInvestingMinor += BigInt(first.amount_minor);
200	    }
201	    const days = dayRange(base, today).slice(1);
202	    const accountPoints = points(days);
203	    const atBase = basePoint.accountValues ?? new Map<string, bigint>();
204	    for (const account of balances.accounts) {
205	      if (account.currency_code !== currency || atBase.has(account.id)) continue;
206	      const first = accountPoints.find(point => point.accountValues?.has(account.id));
207	      if (first) newlyAddedMinor += first.accountValues!.get(account.id)!;
208	      else if (account.archived_at === null || account.archived_at === undefined) { const live = accounts.find(item => item.id === account.id)?.balance.amount_minor; if (live) newlyAddedMinor += BigInt(live); }
209	    }
210	    // Only money the broker's value already shows: a portfolio that is newly added this month, or a transfer no read has seen, isn't in it.
211	    const brokerCounted = !!firstReal && (firstReal <= base || portfolioBefore);
212	    const movedIntoBroker = !brokerCounted ? 0n : transfers.rows.filter(row => {
213	      const shown = brokerShownOn(row, firstReal, reads);
214	      return row.currency_code === currency && row.status === "SETTLED" && !row.is_cancellation && !!shown && shown > base && shown <= today;
215	    }).reduce((sum, row) => sum + BigInt(row.amount_minor), 0n);
216	    const investmentsMinor = investing(today) - investing(base) - movedIntoBroker - newInvestingMinor;
217	    const changeMinor = totalChangeMinor - newlyAddedMinor;
218	    return { base, baseMinor: netWorth(basePoint).get(currency) ?? 0n, totalChangeMinor, changeMinor, moneyMinor: changeMinor - investmentsMinor, investmentsMinor, newlyAddedMinor };
219	  };
220	  return { timeZone, today, now, points, monthSplit, accounts, active, dated, kinds, valuations, firstReal, calculated, windows, unresolved, movedOnBoundaryMinor };
221	}
