285	      parts: { accountsFormatted: money(total.parts.cash), investmentsAndAssetsFormatted: money(total.parts.assets), debtsFormatted: money(total.parts.debts), ...(total.parts.transit ? { betweenYourAccountsFormatted: money(total.parts.trans
286	      leftOut: describeMissingInputs(total.missingInputs, names), freshness, unresolvedTransfers, link,
287	      ...(split ? { thisMonth: { changeFormatted: money(split.changeMinor), moneyInAndOutFormatted: money(split.moneyMinor), investmentsFormatted: money(split.investmentsMinor), newlyAddedFormatted: money(split.newlyAddedMinor), note: "The 
288	      ...(trend ? { trend } : {}) };
