307	// Scalable's own record of money moving in or out of the broker. It lists these as cash rows of type DEPOSIT or WITHDRAWAL;
308	// a withdrawal that bounced comes back as a deposit with the ID RETURN-<withdrawal id> and the opposite amount.
309	
310	const PAGE_SIZE = 100, MAX_PAGES = 1000;
311	const decimal = z.union([z.number().finite(), z.string().regex(/^-?\d+(\.\d+)?$/)]);
312	const listSchema = z.object({
313	  page: z.object({ nextCursor: z.string().nullish() }).optional(),
314	  transactions: z.array(z.object({ id: z.string().min(1), status: z.string().min(1), currency: z.string().nullish(), isCancellation: z.boolean().nullish(), lastEventAt: z.string(), description: z.string().nullish(),
315	    cash: z.object({ transactionType: z.string().nullish(), amount: decimal.nullish() }).nullish() })).default([]),
