318	export type TransferRow = { provider_id: string; type: "DEPOSIT" | "WITHDRAWAL"; amount_minor: string; currency_code: string; occurred_at: string; on_date: string; status: string; is_cancellation: boolean; description: s
319	const RETURN = "RETURN-";
320	
321	/** The transfers in one reply of list_portfolio_transactions. Other cash rows, like interest and tax, are real changes and not transfers. */
322	export function transferRows(reply: unknown, timeZone: string): TransferRow[] {
323	  return listSchema.parse(reply).transactions.flatMap(row => {
324	    const type = row.cash?.transactionType;
325	    if ((type !== "DEPOSIT" && type !== "WITHDRAWAL") || row.cash?.amount == null) return [];
326	    const currency = row.currency ?? "EUR", amount = toMinor(row.cash.amount, currency);
327	    if (amount === "0") return [];
328	    return [{ provider_id: row.id, type, amount_minor: amount, currency_code: currency, occurred_at: row.lastEventAt, on_date: calendarDate(row.lastEventAt, timeZone), status: row.status,
329	      is_cancellation: row.isCancellation === true, description: row.description?.slice(0, 500) ?? null, returns_provider_id: row.id.startsWith(RETURN) ? row.id.slice(RETURN.length) : null }];
330	  });
331	}
