333	/** Every transfer, from the list only: no price charts or per-trade detail calls, so it is cheap to run once after connecting. */
334	export async function readAllTransfers(mcp: Pick<ScalableMcp, "callTool">, timeZone: string) {
335	  const rows = new Map<string, TransferRow>();
336	  let cursor: string | undefined;
337	  for (let page = 0; ; page++) {
338	    if (page === MAX_PAGES) throw new Error("Scalable transactions never finished paging");
339	    const reply = await mcp.callTool("list_portfolio_transactions", { pageSize: PAGE_SIZE, ...(cursor ? { cursor } : {}) });
340	    for (const row of transferRows(reply, timeZone)) rows.set(row.provider_id, row);
341	    cursor = listSchema.parse(reply).page?.nextCursor || undefined;
342	    if (!cursor) return [...rows.values()];
343	  }
344	}
