368	/**
369	 * One try at a connection's calculated history. Separate from syncScalable, so it can't slow down or fail a sync.
370	 * A failed try saves nothing and leaves any earlier days in place; the reason stays on the connection, out of the owner's way.
371	 */
372	export async function rebuildScalableHistory(connection: { id: string; workspace_id: string; portfolio: unknown }, timeZone: string, today: string): Promise<"saved" | "failed" | "skipped"> {
373	  const db = serviceDb();
374	  const [events, items] = await Promise.all([loadWealthEvents(db, connection.workspace_id), loadWealthItems(db, connection.workspace_id, true)]);
375	  const before = firstSyncedOn(valuationHistory(events, items, timeZone), scalableKnownIds([connection.portfolio as ScalableExtras | null]));
376	  // Nothing has synced yet, so there is no date to stop before. The next run tries again.
377	  if (!before) return "skipped";
378	  const failed = async (reason: string) => {
379	    const saved = await db.from("scalable_connections").update({ history_status: "failed", history_checked_on: today, history_error: reason.slice(0, 1000) }).eq("id", connection.id);
380	    if (saved.error) throw new Error(saved.error.message);
381	    return "failed" as const;
382	  };
383	  try {
384	    const result = calculateHistory(await withScalable(connection.id, connection.workspace_id, mcp => readHistoryInput(mcp, timeZone, before), fetch, LOGIN_NEEDED_MS));
385	    if (!result.ok) return await failed(result.reason);
386	    const saved = await db.rpc("replace_scalable_value_history", { p_connection_id: connection.id, p_checked_on: today,
387	      p_rows: result.days.map(day => ({ on_date: day.date, currency_code: "EUR", securities_minor: day.securitiesMinor.toString(), crypto_minor: day.cryptoMinor.toString(), cash_minor: day.cashMinor.toString(), total_min
388	    if (saved.error) throw new Error(saved.error.message);
389	    return "saved";
390	  } catch (error) {
391	    return failed(error instanceof Error ? error.message : "Scalable could not be read");
392	  }
393	}
