403	// Works out past Scalable values for connections without a good history yet, one try per workspace day.
404	export async function GET(request: Request) {
405	  const secret = process.env.CRON_SECRET;
406	  if (!secret || request.headers.get("authorization") !== `Bearer ${secret}`) return Response.json({ error: "Unauthorized" }, { status: 401 });
407	  if (!process.env.NEXT_PUBLIC_SUPABASE_URL || !scalableConfigured()) return Response.json({ error: "Scalable history unavailable" }, { status: 503 });
408	  const db = serviceDb();
409	  const { data, error } = await db.from("scalable_connections").select("id, workspace_id, portfolio, history_status, history_checked_on, transfers_backfilled_at").eq("status", "active").order("id").li
410	  if (error) return Response.json({ error: "Scalable connections unavailable" }, { status: 503 });
411	  const counts = { saved: 0, failed: 0, skipped: 0 };
412	  for (const row of data ?? []) {
413	    try {
414	      const { timezone } = await loadWorkspaceSettings(db, row.workspace_id);
415	      const today = calendarDate(new Date(), timezone);
416	      // Apart from the chart, so a connection with good history still gets its past transfers. A failure retries next hour.
417	      if (!row.transfers_backfilled_at) await backfillScalableTransfers(row, timezone).catch(cause => console.error("Scalable transfers were not read", cause));
418	      if (row.history_status === "ok" || row.history_checked_on === today) continue;
419	      counts[await rebuildScalableHistory(row, timezone, today)]++;
420	    } catch { counts.failed++; }
421	  }
422	  return Response.json(counts);
