65	   * `changeMinor` excludes what's newly added; the total still counts it. Moving your own money is neither.
66	   */
67	  const monthSplit = (currency: string, base = monthEnds(today, 1)[0]) => {
68	    const [basePoint] = points([base]);
69	    if (!basePoint?.known) return null;
70	    const totalChangeMinor = (netWorth(now).get(currency) ?? 0n) - (netWorth(basePoint).get(currency) ?? 0n);
71	    const isLoan = (name: string) => parseIouName(name) !== null;
72	    const portfolioBefore = !!firstReal && firstReal > base && calculated.rows.some(row => row.on_date === base);
73	    const newCovered = (id: string) => portfolioBefore && scalable.knownIds.has(id);
74	    // Loans move with the bank money that paid them, so they're never "new" and belong with money in and out.
75	    const named = new Map(items.map(item => [item.id, item.name]));
76	    const states = valuations.filter(row => row.currency_code === currency && !row.removed && !isLoan(String((row as { name?: string }).name ?? named.get(row.item_id) ?? "")));
