81	    };
82	    const allStates = valuations.filter(row => row.currency_code === currency && !isLoan(String((row as { name?: string }).name ?? named.get(row.item_id) ?? "")));
83	    const counted = (date: string) => [...valueOn(date, allStates).values()].filter(row => !row.removed && !row.linked_account_id);
84	    const investing = (date: string) => counted(date).filter(row => row.kind !== "debt").reduce((sum, row) => sum + BigInt(row.amount_minor), 0n)
85	      + (firstReal && date < firstReal ? BigInt(calculated.rows.find(row => row.on_date === date && row.currency_code === currency)?.total_minor ?? "0") : 0n);
86	    let newlyAddedMinor = 0n, newInvestingMinor = 0n;
87	    for (const row of counted(today)) {
88	      const first = states.filter(state => state.item_id === row.item_id && !state.linked_account_id).reduce<typeof states[number] | null>((earliest, state) => !earliest || state.as_of < earliest.as_of || (state.as_of === earliest.as_of && state.created_at < earliest.created_at) ? state : earliest, null);
89	      if (!first || first.as_of <= base || newCovered(row.item_id)) continue;
90	      newlyAddedMinor += BigInt(first.amount_minor);
91	      if (row.kind !== "debt") newInvestingMinor += BigInt(first.amount_minor);
92	    }
93	    const days = dayRange(base, today).slice(1);
94	    const accountPoints = points(days);
95	    const atBase = basePoint.accountValues ?? new Map<string, bigint>();
96	    for (const account of balances.accounts) {
