102	    // Only money the broker's value already shows: a portfolio that is newly added this month, or a transfer no read has seen, isn't in it.
103	    const brokerCounted = !!firstReal && (firstReal <= base || portfolioBefore);
104	    const movedIntoBroker = !brokerCounted ? 0n : transfers.rows.filter(row => {
105	      const shown = brokerShownOn(row, firstReal, reads);
106	      return row.currency_code === currency && row.status === "SETTLED" && !row.is_cancellation && !!shown && shown > base && shown <= today;
107	    }).reduce((sum, row) => sum + BigInt(row.amount_minor), 0n);
108	    const investmentsMinor = investing(today) - investing(base) - movedIntoBroker - newInvestingMinor;
