118	export async function loadFxRates(db: SupabaseClient, workspaceId: string, displayCurrency: string): Promise<Rate[]> {
119	  const { data, error } = await db.from("fx_rates").select("from_currency, to_currency, rate_text, rate_date, source").eq("workspace_id", workspaceId).eq("to_currency", displayCurrency).order("rate_date", { ascending: false }).order("created_at", { ascending: false });
120	  if (error) throw error;
