124	/** Today's total in one currency: dated balances and values, each converted with the latest rate on or before its date. An input that can't be converted is left out and named. */
125	export function convertedNetWorth(model: NetWorthModel, rates: Rate[], displayCurrency: string) {
126	  const missingInputs: string[] = [];
127	  const parts = { cash: 0n, assets: 0n, debts: 0n, transit: 0n };
128	  let totalMinor = 0n, convertedCount = 0;
129	  const add = (amountMinor: bigint, from: string, asOf: string, source: string, name: string, part: keyof typeof parts) => {
130	    const rate = from === displayCurrency ? undefined : rates.find(row => row.from_currency === from && String(row.rate_date).slice(0, 10) <= asOf);
131	    try {
132	      const result = convertFx({ amountMinor, from, to: displayCurrency, rate: rate?.rate_text, source: rate?.source ?? source, date: rate ? String(rate.rate_date).slice(0, 10) : asOf });
133	      if (result.status === "available") { totalMinor += result.converted.amountMinor; convertedCount += 1; parts[part] += result.converted.amountMinor; }
134	      else missingInputs.push(...result.missingInputs.map(input => `${input} for ${name}`));
135	    } catch { missingInputs.push(`rate:${from}->${displayCurrency} for ${name}`); }
136	  };
137	  for (const account of model.accounts) {
138	    const { balance } = account;
139	    if (balance.amount_minor === null) { missingInputs.push(`balance:${account.name}`); continue; }
140	    add(BigInt(balance.amount_minor), balance.currency_code, calendarDate(balance.as_of!, model.timeZone), balance.provenance || "balance", account.name, "cash");
141	  }
142	  missingInputs.push(...model.dated.missingInputs);
143	  for (const valuation of model.dated.included) add(valuation.amountMinor, valuation.currencyCode, valuation.asOf, valuation.provenance, valuation.name, model.kinds.get(valuation.id) === "debt" ? "debts" : "assets");
144	  for (const [currency, amount] of model.now.transit) add(amount, currency, model.today, "own transfer", "Money between your accounts", "transit");
145	  return { totalMinor, parts, missingInputs, convertedCount };
146	}
