155	/**
156	 * Net worth as chat, the voice call and artifacts read it: the same calculation as Home and Wealth, for today or a past date, with what was
157	 * left out and how fresh each input is. Past days are in each currency as recorded, without conversion (issue #158).
158	 */
159	export async function readNetWorth({ supabase, workspace }: Reader, input: unknown) {
160	  const { date, days } = netWorthInput.parse(input);
161	  const [evidence, rates] = await Promise.all([loadNetWorthEvidence(supabase, workspace), loadFxRates(supabase, workspace.id, workspace.display_currency)]);
162	  const model = netWorthModel(evidence);
163	  const money = (minor: bigint | string, currency = workspace.display_currency) => formatMoney(minor, currency, workspace.locale);
164	  const on = date ?? model.today;
165	  if (on > model.today) throw new Error("That date is in the future");
166	  const freshness = { accounts: model.accounts.map(account => ({ name: account.name, balanceAsOf: account.balance.as_of, status: account.balance.status, warnings: account.balance.warnings })),
167	    valuesNotFromToday: model.dated.outdated.map(row => ({ name: row.name, asOf: row.asOf })) };
168	  const trend = days ? model.points(dayRange(new Date(Date.parse(`${model.today}T00:00:00Z`) - (days - 1) * 86400000).toISOString().slice(0, 10), model.today)).filter(point => point.known)
169	    .map(point => ({ date: point.date, amountMinor: (netWorth(point).get(workspace.display_currency) ?? 0n).toString(), amountFormatted: money(netWorth(point).get(workspace.display_currency) ?? 0n), ...(point.uncertain.length ? { notProven: point.uncertain } : {}) })) : undefined;
170	  const unresolvedTransfers = model.unresolved.map(item => ({ date: item.date, label: item.label, amountFormatted: money(item.amountMinor, item.currencyCode), reason: item.reason }));
171	  const link = "/money/wealth";
172	  if (on === model.today) {
173	    const total = convertedNetWorth(model, rates, workspace.display_currency);
174	    const split = model.monthSplit(workspace.display_currency);
175	    const names = new Map(model.active.map(item => [item.id, item.name]));
176	    return { date: on, currencyCode: workspace.display_currency, amountMinor: total.totalMinor.toString(), amountFormatted: money(total.totalMinor),
177	      parts: { accountsFormatted: money(total.parts.cash), investmentsAndAssetsFormatted: money(total.parts.assets), debtsFormatted: money(total.parts.debts), ...(total.parts.transit ? { betweenYourAccountsFormatted: money(total.parts.transit) } : {}) },
178	      leftOut: describeMissingInputs(total.missingInputs, names), freshness, unresolvedTransfers, link,
179	      ...(split ? { thisMonth: { changeFormatted: money(split.changeMinor), moneyInAndOutFormatted: money(split.moneyMinor), investmentsFormatted: money(split.investmentsMinor), newlyAddedFormatted: money(split.newlyAddedMinor), note: "The change excludes what's newly added this month; the total includes it." } } : {}),
180	      ...(trend ? { trend } : {}) };
181	  }
182	  const [point] = model.points([on]);
183	  if (!point.known) return { date: on, known: false, note: "Nothing is on record that far back: the history starts where account data starts.", link, ...(trend ? { trend } : {}) };
184	  const totals = netWorth(point);
185	  return { date: on, known: true, currencyCode: workspace.display_currency, amountMinor: (totals.get(workspace.display_currency) ?? 0n).toString(), amountFormatted: money(totals.get(workspace.display_currency) ?? 0n),
186	    otherCurrencies: [...totals].filter(([currency]) => currency !== workspace.display_currency).map(([currency, amount]) => ({ currencyCode: currency, amountFormatted: money(amount, currency) })),
187	    parts: { accountsFormatted: money(point.accounts.get(workspace.display_currency) ?? 0n), investmentsAndAssetsFormatted: money(point.assets.get(workspace.display_currency) ?? 0n), debtsFormatted: money(point.debts.get(workspace.display_currency) ?? 0n) },
188	    ...(model.firstReal && on < model.firstReal ? { calculatedPortfolio: "Scalable's value on this day is calculated from its transactions and past prices." } : {}),
189	    ...(point.uncertain.length ? { notProven: point.uncertain } : {}), unresolvedTransfers, link, ...(trend ? { trend } : {}) };
190	}
