3	// Archiving an account that still holds money: the owner says where it went, and that answer becomes ordinary records.
4	// Moved or taken as cash, the money is a linked own transfer dated today, so net worth doesn't change. Gone, it leaves
5	// as a normal posting. Nothing here hides money: every path ends with the account at zero through a row you can see.
6	
7	export const closingAnswerSchema = z.discriminatedUnion("outcome", [
8	  z.object({ outcome: z.literal("moved"), targetAccountId: z.uuid() }),
9	  z.object({ outcome: z.literal("cash"), targetAccountId: z.uuid().optional() }),
10	  z.object({ outcome: z.literal("gone") }),
11	]);
12	export type ClosingAnswer = z.infer<typeof closingAnswerSchema>;
13	
14	type Account = { id: string; name: string; type?: string; currency_code: string; archived_at?: string | null };
15	
16	/** The other accounts the money can go to. */
17	export const closingTargets = <T extends Account>(account: Account, accounts: T[]) => accounts.filter(other => other.id !== account.id && !other.archived_at && other.currency_code === account.currency_code);
18	
19	/** The rows an answer needs. `createCash` means there is no Cash account yet and the action makes one. */
20	export function closingPlan(account: Account, balanceMinor: bigint, answer: ClosingAnswer, accounts: Account[]) {
21	  if (balanceMinor === 0n) throw new Error("This account has no money to account for");
22	  const targets = closingTargets(account, accounts);
23	  if (answer.outcome === "gone") return { out: { amountMinor: -balanceMinor, description: "Closing balance gone" }, into: null, target: null, createCash: false };
24	  let target: Account | null;
25	  let createCash = false;
26	  if (answer.outcome === "moved") {
27	    target = targets.find(other => other.id === answer.targetAccountId) ?? null;
28	    if (!target) throw new Error(`Choose another ${account.currency_code} account`);
29	  } else {
30	    const cash = targets.filter(other => other.type === "cash");
31	    target = answer.targetAccountId ? cash.find(other => other.id === answer.targetAccountId) ?? null : cash.length === 1 ? cash[0] : null;
32	    if (!target && (answer.targetAccountId || cash.length > 1)) throw new Error("Choose a Cash account");
33	    createCash = !target;
34	  }
35	  const name = target?.name ?? "Cash";
36	  return { out: { amountMinor: -balanceMinor, description: `Closing balance moved to ${name}`.slice(0, 500) }, into: { amountMinor: balanceMinor, description: `Closing balance from ${account.name}`.slice(0, 500) }, target, createCash };
37	}
