21	export async function editAccount(_state: { error?: string }, form: FormData): Promise<{ error?: string }> {
22	  try {
23	  const { supabase, workspace } = await requireWorkspace();
24	  // Asked again here, not only in the form: archiving can't drop money from net worth without an answer.
25	  if (form.get("operation") === "archive") {
26	    const evidence = await loadBalanceEvidence(supabase, workspace.id);
27	    const account = resolveBalances(evidence.accounts.filter(row => row.id === form.get("accountId")), evidence.snapshots, evidence.ledger, evidence.asOf, workspace.timezone)[0];
28	    if (account?.balance.status === "ambiguous") throw new Error("Settle this account's balance before archiving it");
29	    if (account && BigInt(account.balance.amount_minor ?? "0") !== 0n) throw new Error("This account still holds money. Say what happens to it first.");
30	  }
31	  const patch = form.get("operation") === "archive" ? { archived: true }
32	    : form.get("operation") === "restore" ? { archived: false }
33	    : { name: z.string().trim().min(1).max(120).parse(form.get("name")), type: accountType.parse(form.get("type")) };
34	  const { error } = await supabase.rpc("edit_money_metadata", {
35	    p_entity_type: "account", p_id: z.uuid().parse(form.get("accountId")),
36	    p_expected_version: version.parse(form.get("version")), p_patch: patch, p_request_id: z.uuid().parse(form.get("requestId")),
37	  });
38	  if (error) throw new Error(error.message);
39	  } catch (error) {
40	    return { error: error instanceof z.ZodError ? "Enter a name of 1 to 120 characters" : error instanceof Error ? error.message : "Could not update account" };
41	  }
42	  revalidatePath("/", "layout");
43	  redirect(`/money/accounts?saved=account:${String(form.get("accountId"))}#account-${String(form.get("accountId"))}`);
44	}
