46	/**
47	 * Archives an account that still holds money, after the owner said where it went. Each row uses the same audited tools as
48	 * by hand, keyed by this request, so pressing again after a failure can't add the money twice. Restoring the account
49	 * leaves these rows in place; each can be undone from its transaction.
50	 */
51	export async function archiveWithAnswer(_state: { error?: string }, form: FormData): Promise<{ error?: string }> {
52	  const accountId = String(form.get("accountId"));
53	  try {
54	    const { supabase, workspace } = await requireWorkspace();
55	    const requestId = z.uuid().parse(form.get("requestId"));
56	    const answer = closingAnswerSchema.parse({ outcome: form.get("outcome"), ...(form.get("targetAccountId") ? { targetAccountId: form.get("targetAccountId") } : {}) });
57	    const evidence = await loadBalanceEvidence(supabase, workspace.id);
58	    const account = resolveBalances(evidence.accounts.filter(row => row.id === accountId), evidence.snapshots, evidence.ledger, evidence.asOf, workspace.timezone)[0];
59	    if (!account || account.archived_at) throw new Error("Account not found");
60	    if (account.balance.amount_minor === null) throw new Error("Settle this account's balance before archiving it");
61	    const plan = closingPlan(account, BigInt(account.balance.amount_minor), answer, evidence.accounts);
62	    const today = calendarDate(new Date(evidence.asOf), workspace.timezone);
63	    let targetId = plan.target?.id ?? null;
64	    if (plan.createCash) {
65	      // Keyed by this request, so pressing again after a failure finds the same account.
66	      targetId = stableId(`${requestId}:cash`);
67	      const existing = await supabase.from("accounts").select("id").eq("id", targetId).maybeSingle();
68	      if (existing.error) throw new Error(existing.error.message);
69	      if (!existing.data) {
70	        const created = await supabase.from("accounts").insert({ id: targetId, workspace_id: workspace.id, name: "Cash", type: "cash", currency_code: account.currency_code });
71	        if (created.error) throw new Error(created.error.message);
72	      }
73	      // A new account counts from a balance; the money moved in today is what's in it.
74	      const dayBefore = new Date(Date.parse(`${today}T00:00:00Z`) - 86400000).toISOString().slice(0, 10);
75	      const opening = await supabase.rpc("record_manual_balance", { p_account_id: targetId, p_amount_minor: "0", p_date: dayBefore, p_reviewed: false, p_covered_transactions: null, p_expected_snapshot_id: null, p_expected_version: 0, p_request_id: stableId(`${requestId}:opening`) });
76	      if (opening.error) throw new Error(opening.error.message);
77	    }
78	    const post = async (target: string, row: { amountMinor: bigint; description: string }, part: string) => {
79	      const { data, error } = await supabase.rpc("create_manual_transaction", { p_account_id: target, p_posted_on: today, p_description: row.description, p_amount_minor: row.amountMinor.toString(), p_status: "posted", p_category_id: null, p_note: "Added when archiving an account", p_request_id: stableId(`${requestId}:${part}`) });
80	      if (error) throw new Error(error.message);
81	      const saved = await supabase.from("transactions").select("id, kind, version").eq("id", data.id).single();
82	      if (saved.error) throw new Error(saved.error.message);
83	      return saved.data as { id: string; kind: string; version: number };
84	    };
85	    const out = await post(accountId, plan.out, "out");
86	    if (plan.into && targetId) {
87	      const into = await post(targetId, plan.into, "in");
88	      if (out.kind === "ordinary" && into.kind === "ordinary") {
89	        const linked = await supabase.rpc("link_transactions", { p_operation: "transfer", p_primary_id: plan.into.amountMinor > 0n ? out.id : into.id, p_expected_version: plan.into.amountMinor > 0n ? out.version : into.version,
90	          p_other_id: plan.into.amountMinor > 0n ? into.id : out.id, p_other_version: plan.into.amountMinor > 0n ? into.version : out.version, p_fx_rate_id: null, p_fees: [], p_request_id: stableId(`${requestId}:link`) });
91	        if (linked.error) throw new Error(linked.error.message);
92	      }
93	    }
94	    const fresh = await supabase.from("accounts").select("version").eq("id", accountId).single();
95	    if (fresh.error) throw new Error(fresh.error.message);
96	    const { error } = await supabase.rpc("edit_money_metadata", { p_entity_type: "account", p_id: accountId, p_expected_version: fresh.data.version, p_patch: { archived: true }, p_request_id: stableId(`${requestId}:archive`) });
97	    if (error) throw new Error(error.message);
98	  } catch (error) {
99	    return { error: error instanceof z.ZodError ? "Choose what happened to the money" : error instanceof Error ? error.message : "Could not archive this account" };
100	  }
101	  revalidatePath("/", "layout");
102	  redirect(`/money/accounts?saved=account:${accountId}#account-${accountId}`);
103	}
