196	/** Raises one "your own money?" card per row, once: a declined card is never raised again. */
197	async function proposeOwnNames(db: SupabaseClient, workspaceId: string, rows: TransferCandidate[], seen: TransferCandidate[], own: OwnAccounts) {
198	  const known = await db.from("agent_proposals").select("conflict_key").eq("workspace_id", workspaceId).is("run_id", null).eq("kind", "own_transfer").limit(5000);
199	  if (known.error) throw new Error(known.error.message);
200	  const answered = new Set((known.data ?? []).map(row => String(row.conflict_key).replace(/^own_transfer:/, "")));
201	  const found = ownNameSuggestions(rows, seen, own, answered);
202	  if (!found.length) return 0;
203	  const { locale } = await loadWorkspaceSettings(db, workspaceId);
204	  const byId = new Map(rows.map(row => [row.id, row]));
205	  const cards = found.map(({ transactionId, name }) => {
206	    const row = byId.get(transactionId)!, money = formatMoney(row.amountMinor < 0n ? -row.amountMinor : row.amountMinor, row.currencyCode, locale);
207	    return { workspace_id: workspaceId, agent: "chat", kind: "own_transfer", conflict_key: `own_transfer:${transactionId}`, confidence: 70,
208	      title: (row.amountMinor < 0n ? `${money} to ${name}: your own account?` : `${money} from ${name}: your own account?`).slice(0, 200),
209	      detail: `You sent money under the name ${name} to one of your own accounts before. If this is yours too, it moves to transfers and stops counting as ${row.amountMinor < 0n ? "spending" : "income"}.`,
210	      evidence: { facts: [], transactions: [{ id: row.id, date: row.postedOn, description: row.text ?? "", amountMinor: row.amountMinor.toString(), currency: row.currencyCode }], links: [] },
211	      payload: ownTransferPayloadSchema.parse({ transactionId, name }) };
212	  });
213	  const { data, error } = await db.from("agent_proposals").insert(cards).select("id");
214	  // A concurrent sync raised the same card first.
215	  if (error && error.code !== "23505") throw new Error(error.message);
216	  return data?.length ?? 0;
217	}
