219	/** Raises one "add it to your Cash account?" card per recent withdrawal, once: a declined card is never raised again. */
220	async function proposeCashWithdrawals(db: SupabaseClient, workspaceId: string, rows: TransferCandidate[]) {
221	  const { locale, timezone } = await loadWorkspaceSettings(db, workspaceId);
222	  const known = await db.from("agent_proposals").select("conflict_key").eq("workspace_id", workspaceId).is("run_id", null).eq("kind", "cash_withdrawal").limit(5000);
223	  if (known.error) throw new Error(known.error.message);
224	  const answered = new Set((known.data ?? []).map(row => String(row.conflict_key).replace(/^cash_withdrawal:/, "")));
225	  const found = cashWithdrawals(rows, calendarDate(new Date(), timezone), answered);
226	  if (!found.length) return 0;
227	  const cards = found.map(row => {
228	    const amount = -row.amountMinor, money = formatMoney(amount, row.currencyCode, locale);
229	    return { workspace_id: workspaceId, agent: "chat", kind: "cash_withdrawal", conflict_key: `cash_withdrawal:${row.id}`, confidence: 90,
230	      title: `${money} from a cash machine: add it to your Cash account?`.slice(0, 200),
231	      detail: "Until you add it, it counts as money that left. Once it's in Cash, your net worth stays the same; after spending, update the balance whenever you like.",
232	      evidence: { facts: [], transactions: [{ id: row.id, date: row.postedOn, description: row.text ?? "", amountMinor: row.amountMinor.toString(), currency: row.currencyCode }], links: [] },
233	      payload: { transactionId: row.id, amountMinor: amount.toString(), currencyCode: row.currencyCode, date: row.postedOn } };
234	  });
235	  const { data, error } = await db.from("agent_proposals").insert(cards).select("id");
236	  if (error && error.code !== "23505") throw new Error(error.message);
237	  return data?.length ?? 0;
238	}
