240	/** Find and link transfers between the owner's accounts. The service role acts for the owner. */
241	export async function linkOwnTransfers(db: SupabaseClient, workspaceId: string) {
242	  const [own, rows, legs, transfers, scalable] = await Promise.all([loadOwnAccounts(db, workspaceId), loadTransferCandidates(db, workspaceId), loadLegs(db, workspaceId),
243	    loadRows(db, workspaceId, "transfer"), db.from("scalable_connections").select("id", { count: "exact", head: true }).eq("workspace_id", workspaceId).eq("status", "active")]);
244	  if (scalable.error) throw new Error(scalable.error.message);
245	  const { pairs, single, named } = findOwnTransfers(rows, own, legs, { scalable: (scalable.count ?? 0) > 0 });
246	  const byId = new Map(rows.map(row => [row.id, row]));
247	  let linked = 0, marked = 0, skipped = 0;
248	  for (const pair of pairs) {
249	    const out = byId.get(pair.outId)!, into = byId.get(pair.inId)!;
250	    // The RPC rejects pairs it can't prove (e.g. a documented fee); those stay for manual review.
251	    const { error } = await db.rpc("link_transactions", { p_operation: "transfer", p_primary_id: out.id, p_expected_version: out.version,
252	      p_other_id: into.id, p_other_version: into.version, p_fx_rate_id: null, p_fees: [], p_request_id: randomUUID() });
253	    if (error) skipped++; else linked++;
254	  }
255	  for (const item of single) {
256	    const expectedVersion = byId.get(item.transactionId)!.version;
257	    const { error } = item.identifierId
258	      ? await db.rpc("mark_own_account_transfer", { p_transaction_id: item.transactionId, p_expected_version: expectedVersion, p_identifier_id: item.identifierId })
259	      : await db.rpc("mark_own_iban_transfer", { p_transaction_id: item.transactionId, p_expected_version: expectedVersion, p_iban: item.iban });
260	    if (error) skipped++; else marked++;
261	  }
262	  for (const item of named) {
263	    const { error } = await db.rpc("mark_own_named_transfer", { p_transaction_id: item.transactionId, p_expected_version: byId.get(item.transactionId)!.version, p_kind: item.account });
264	    if (error) skipped++; else marked++;
265	  }
266	  const handled = new Set([...pairs.flatMap(pair => [pair.outId, pair.inId]), ...single.map(item => item.transactionId), ...named.map(item => item.transactionId)]);
267	  const suggested = await proposeOwnNames(db, workspaceId, rows.filter(row => !handled.has(row.id)), [...rows, ...transfers], own);
268	  // Rows marked as cash a moment ago are transfers now; either way it is the bank's wording that counts.
269	  const cashCards = await proposeCashWithdrawals(db, workspaceId, [...rows.filter(row => !handled.has(row.id) || named.some(item => item.transactionId === row.id && item.account === "cash")), ...transfers]);
270	  return { linked, marked, skipped, suggested, cashCards };
271	}
