1	// Money moving between the owner's own accounts is one amount, even while its two sides land on different days. This works out,
2	// at read time, which days count it twice or not at all, and how much to add back on those days. No record is rewritten:
3	// new statements simply change the answer the next time it is read, and earlier days correct themselves.
4	
5	export const TRANSIT_MATCH_DAYS = 3;
6	const FOREVER = "9999-12-31";
7	
8	export type BrokerTransfer = { provider_id: string; type: string; amount_minor: string; currency_code: string; on_date: string; occurred_at: string; status: string; is_cancellation?: boolean; returns_provider_id: string | null; description?: string | null };
9	/** A posted bank row that is an own transfer. `provesBroker`: its IBAN or wording says the other side is the broker. `ownAccount`: it names one of the owner's tracked accounts. */
10	export type BankLeg = { id: string; accountId: string; amountMinor: bigint; currencyCode: string; postedOn: string; transferId: string | null; provesBroker: boolean; ownAccount: boolean; text?: string };
11	/** On days from <= date < to, `amountMinor` is added. A broker side counts only on days the broker has a value. */
12	export type TransitWindow = { from: string; to: string; amountMinor: bigint; currencyCode: string; kind: "returned" | "matched" | "linked"; broker: boolean; accounts: string[]; key: string };
13	export type UnresolvedTransfer = { key: string; side: "broker" | "bank"; date: string; amountMinor: bigint; currencyCode: string; reason: "missing" | "ambiguous"; label: string };
14	
15	const gap = (a: string, b: string) => Math.abs(Date.parse(`${a}T00:00:00Z`) - Date.parse(`${b}T00:00:00Z`)) / 86400000;
16	const abs = (value: bigint) => value < 0n ? -value : value;
17	const settled = (transfer: BrokerTransfer) => transfer.status === "SETTLED" && !transfer.is_cancellation;
18	
19	/** Between two opposite sides, the first to land is what's wrong until the second does: its effect is taken off. */
20	function window(first: { date: string; signed: bigint }, second: { date: string }, amount: bigint, rest: Omit<TransitWindow, "from" | "to" | "amountMinor">): TransitWindow | null {
21	  if (first.date === second.date) return null;
22	  const [early, late] = first.date < second.date ? [first, second] : [second as typeof first, first];
23	  const sign = (first.date < second.date ? first.signed : -first.signed) > 0n ? -1n : 1n;
24	  return { from: early.date, to: late.date, amountMinor: sign * amount, ...rest };
25	}
26	
27	/**
28	 * The day a broker transfer shows in the broker's value. Before the first real sync, the calculated history has it on its own date.
29	 * After that, it shows from the first sync read after it happened. Null means no read has seen it yet.
30	 */
31	export function brokerShownOn(transfer: Pick<BrokerTransfer, "on_date" | "occurred_at">, firstReal: string | null, reads: { as_of: string; created_at: string }[]) {
32	  if (firstReal && transfer.on_date < firstReal) return transfer.on_date;
33	  const occurred = Date.parse(transfer.occurred_at);
34	  return reads.filter(read => read.as_of >= transfer.on_date && Date.parse(read.created_at) >= occurred).map(read => read.as_of).sort()[0] ?? null;
35	}
36	
37	/**
38	 * Pairs the two sides of every own transfer that can be proven, and lists the ones that can't. A pair needs opposite amounts, the same
39	 * currency, a bank row proven to be the broker's by IBAN or wording, and exactly one candidate each way within the window. A side is
40	 * never used twice. A returned withdrawal pairs with its return by Scalable's own ID, so it needs no bank row at all.
41	 */
42	export function matchTransfers({ transfers, legs, firstReal, reads, complete, coveredFrom }: {
43	  transfers: BrokerTransfer[]; legs: BankLeg[]; firstReal: string | null; reads: { as_of: string; created_at: string }[];
44	  /** The whole broker list has been read, so a bank row with no broker side really is missing one. */
45	  complete: boolean;
46	  /** The first day of bank data: older broker transfers can't have a bank side on record. */
47	  coveredFrom: string | null;
48	}) {
49	  const live = transfers.filter(settled);
50	  const shown = (transfer: BrokerTransfer) => brokerShownOn(transfer, firstReal, reads) ?? FOREVER;
51	  const windows: TransitWindow[] = [], unresolved: UnresolvedTransfer[] = [];
52	  const byId = new Map(live.map(transfer => [transfer.provider_id, transfer]));
53	
54	  const returned = new Set<string>();
55	  for (const back of live) {
56	    const out = back.returns_provider_id ? byId.get(back.returns_provider_id) : undefined;
57	    if (!out) continue;
58	    returned.add(back.provider_id); returned.add(out.provider_id);
59	    const made = window({ date: shown(out), signed: BigInt(out.amount_minor) }, { date: shown(back) }, abs(BigInt(out.amount_minor)), { currencyCode: out.currency_code, kind: "returned", broker: true, accounts: [], key: `returned:${out.provider_id}` });
60	    if (made) windows.push(made);
61	  }
62	
63	  const open = live.filter(transfer => !returned.has(transfer.provider_id));
64	  // Own-reference wording proves a row too: the note on the bank's row is the note Scalable shows on the deposit.
65	  const reference = (leg: BankLeg, transfer: BrokerTransfer) => { const note = transfer.description?.replace(/\s+/g, " ").trim().toLowerCase(); return !!note && note.length >= 8 && !!leg.text && leg.text.replace(/\s+/g, " ").toLowerCase().includes(note); };
66	  const fits = (leg: BankLeg, transfer: BrokerTransfer) => leg.amountMinor === -BigInt(transfer.amount_minor) && leg.currencyCode === transfer.currency_code && gap(leg.postedOn, transfer.on_date) <= TRANSIT_MATCH_DAYS && (leg.provesBroker || reference(leg, transfer));
67	  const unlinked = legs.filter(leg => !leg.transferId);
68	  const paired = new Set<string>(), seenBroker = new Set<string>();
69	  const legsFor = (transfer: BrokerTransfer) => unlinked.filter(leg => fits(leg, transfer));
70	  const transfersFor = (leg: BankLeg) => open.filter(transfer => fits(leg, transfer));
71	  const ambiguous = (transfer: BrokerTransfer) => legsFor(transfer).length > 1 || legsFor(transfer).some(leg => transfersFor(leg).length > 1);
72	  for (const transfer of open) {
73	    if (ambiguous(transfer) || !legsFor(transfer).length) continue;
74	    const leg = legsFor(transfer)[0];
75	    paired.add(leg.id); seenBroker.add(transfer.provider_id);
76	    const made = window({ date: shown(transfer), signed: BigInt(transfer.amount_minor) }, { date: leg.postedOn }, abs(leg.amountMinor), { currencyCode: leg.currencyCode, kind: "matched", broker: true, accounts: [leg.accountId], key: `matched:${transfer.provider_id}` });
77	    if (made) windows.push(made);
78	  }
79	
80	  for (const transfer of open) {
81	    if (seenBroker.has(transfer.provider_id) || (coveredFrom && gap(transfer.on_date, coveredFrom) > TRANSIT_MATCH_DAYS && transfer.on_date < coveredFrom)) continue;
82	    unresolved.push({ key: `broker:${transfer.provider_id}`, side: "broker", date: transfer.on_date, amountMinor: BigInt(transfer.amount_minor), currencyCode: transfer.currency_code, reason: ambiguous(transfer) ? "ambiguous" : "missing",
83	      label: `Scalable ${transfer.type === "DEPOSIT" ? "deposit" : "withdrawal"}` });
84	  }
85	  for (const back of live) if (back.returns_provider_id && !byId.has(back.returns_provider_id))
86	    unresolved.push({ key: `broker:${back.provider_id}`, side: "broker", date: back.on_date, amountMinor: BigInt(back.amount_minor), currencyCode: back.currency_code, reason: "missing", label: "Scalable returned withdrawal" });
87	  if (complete) for (const leg of unlinked) {
88	    if (paired.has(leg.id) || (!leg.provesBroker && !leg.ownAccount)) continue;
89	    unresolved.push({ key: `bank:${leg.id}`, side: "bank", date: leg.postedOn, amountMinor: leg.amountMinor, currencyCode: leg.currencyCode, reason: transfersFor(leg).some(ambiguous) ? "ambiguous" : "missing", label: leg.text?.slice(0, 80) ?? "Own transfer" });
90	  }
91	
92	  const legById = new Map(legs.map(leg => [leg.id, leg]));
93	  for (const leg of legs) {
94	    const other = leg.transferId ? legById.get(leg.transferId) : undefined;
95	    // Each linked pair once. Other currencies aren't comparable here, and an exact fee stays a real change on its own date.
96	    if (!other || leg.id > other.id || leg.currencyCode !== other.currencyCode || (leg.amountMinor < 0n) === (other.amountMinor < 0n)) continue;
97	    const amount = abs(leg.amountMinor) < abs(other.amountMinor) ? abs(leg.amountMinor) : abs(other.amountMinor);
98	    const made = window({ date: leg.postedOn, signed: leg.amountMinor }, { date: other.postedOn }, amount, { currencyCode: leg.currencyCode, kind: "linked", broker: false, accounts: [leg.accountId, other.accountId], key: `linked:${leg.id}` });
99	    if (made) windows.push(made);
100	  }
101	  return { windows, unresolved: unresolved.sort((a, b) => b.date.localeCompare(a.date) || a.key.localeCompare(b.key)) };
102	}
103	
104	/** What to add on a date, per currency. `shows` says whether a window's sides have balances that day: a correction only applies to what's already counted. */
105	export function transitOn(windows: TransitWindow[], date: string, shows: (window: TransitWindow) => boolean = () => true) {
106	  const total = new Map<string, bigint>();
107	  for (const item of windows) if (item.from <= date && date < item.to && shows(item)) total.set(item.currencyCode, (total.get(item.currencyCode) ?? 0n) + item.amountMinor);
108	  return total;
109	}
