28	create function public.replace_scalable_value_history(p_connection_id uuid, p_rows jsonb, p_checked_on date) returns integer
29	language plpgsql security definer set search_path='' as $$
30	declare connection public.scalable_connections%rowtype; saved integer;
31	begin
32	  if p_connection_id is null or p_checked_on is null or jsonb_typeof(p_rows) is distinct from 'array' then
33	    raise exception 'Invalid Scalable value history' using errcode = '22023'; end if;
34	  select * into connection from public.scalable_connections where id = p_connection_id and status = 'active' for update;
35	  if not found then raise exception 'Scalable connection is not active' using errcode = 'P0002'; end if;
36	  delete from public.scalable_value_history where workspace_id = connection.workspace_id;
37	  insert into public.scalable_value_history(workspace_id, on_date, currency_code, securities_minor, crypto_minor, cash_minor, total_minor)
38	    select connection.workspace_id, row.on_date, row.currency_code, row.securities_minor, row.crypto_minor, row.cash_minor, row.total_minor
39	    from jsonb_to_recordset(p_rows) as row(on_date date, currency_code text, securities_minor bigint, crypto_minor bigint, cash_minor bigint, total_minor bigint);
40	  get diagnostics saved = row_count;
41	  update public.scalable_connections set history_status = 'ok', history_checked_on = p_checked_on, history_error = null where id = p_connection_id;
42	  return saved;
43	end;
44	$$;
45	revoke all on function public.replace_scalable_value_history(uuid, jsonb, date) from public, anon, authenticated;
46	grant execute on function public.replace_scalable_value_history(uuid, jsonb, date) to service_role;
